package com.leetcode.backend.model;import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="learning_paths")public class LearningPath{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String title;@Column(columnDefinition="TEXT")private String description;private boolean published;@OneToMany(mappedBy="path",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("position")private List<LearningPathSection>sections=new ArrayList<>();public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public boolean isPublished(){return published;}public void setPublished(boolean v){published=v;}public List<LearningPathSection>getSections(){return sections;}}
